package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.JsonFormat;
import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
import com.fasterxml.jackson.annotation.JsonProperty;
import com.fasterxml.jackson.annotation.JsonTypeInfo;
import com.fasterxml.jackson.annotation.ObjectIdGenerator;
import com.fasterxml.jackson.annotation.ObjectIdGenerators;
import com.fasterxml.jackson.annotation.ObjectIdResolver;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser.NumberType;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.deser.BeanDeserializerBuilder;
import com.fasterxml.jackson.databind.deser.impl.*;
import com.fasterxml.jackson.databind.deser.std.StdDelegatingDeserializer;
import com.fasterxml.jackson.databind.deser.std.StdDeserializer;
import com.fasterxml.jackson.databind.exc.IgnoredPropertyException;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.ser.BeanPropertyMap;
import com.fasterxml.jackson.databind.type.ClassKey;
import com.fasterxml.jackson.databind.util.*;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Constructor;
import java.lang.reflect.InvocationTargetException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

public class BeanDeserializerBase_createContextual_TriageGen0Test {

    private DeserializationContext ctxt;
    private BeanProperty property;
    private AnnotationIntrospector intr;
    private BeanDescription beanDesc;
    private BeanDeserializerBuilder builder;
    private BeanPropertyMap beanProperties;

    // Concrete implementation for testing abstract class
    private static class TestBeanDeserializer extends BeanDeserializer {
        protected TestBeanDeserializer(BeanDeserializerBuilder builder, BeanDescription beanDesc, BeanPropertyMap properties, Map<String, SettableBeanProperty> backRefs, Set<String> ignorableProps, boolean ignoreAllUnknown, boolean hasViews) {
            super(builder, beanDesc, properties, backRefs, ignorableProps, ignoreAllUnknown, hasViews);
        }

        @Override
        public JsonDeserializer<Object> unwrappingDeserializer(NameTransformer unwrapper) { return null; }
        @Override
        protected BeanDeserializer asArrayDeserializer() { return this; }
    }

    @Before
    public void setup() {
        ctxt = mock(DeserializationContext.class);
        property = mock(BeanProperty.class);
        intr = mock(AnnotationIntrospector.class);
        beanDesc = mock(BeanDescription.class);
        builder = mock(BeanDeserializerBuilder.class);
        beanProperties = mock(BeanPropertyMap.class);

        when(ctxt.getAnnotationIntrospector()).thenReturn(intr);
        when(beanDesc.getBeanClass()).thenReturn(Object.class);
        when(beanDesc.getProperties()).thenReturn(Collections.emptyList());
    }

    private TestBeanDeserializer createDeserializer() {
        return new TestBeanDeserializer(builder, beanDesc, beanProperties, new HashMap<>(), new HashSet<>(), true, false);
    }

    @Test
    public void testCreateContextual_NullPropertyOrIntr() throws JsonMappingException {
        TestBeanDeserializer deser = createDeserializer();

        // Case 1: property is null
        JsonDeserializer<?> result1 = deser.createContextual(ctxt, null);
        assertEquals(deser, result1);

        // Case 2: intr is null
        when(ctxt.getAnnotationIntrospector()).thenReturn(null);
        JsonDeserializer<?> result2 = deser.createContextual(ctxt, property);
        assertEquals(deser, result2);
    }

    @Test
    public void testCreateContextual_WithObjectIdInfo_PropertyGenerator_Success() throws Exception {
        TestBeanDeserializer deser = createDeserializer();
        AnnotatedMember member = mock(AnnotatedMember.class);
        when(property.getMember()).thenReturn(member);
        when(intr.findObjectIdInfo(member)).thenReturn(mock(ObjectIdInfo.class));

        ObjectIdInfo mockInfo = mock(ObjectIdInfo.class);
        when(intr.findObjectIdInfo(member)).thenReturn(mockInfo);
        when(intr.findObjectReferenceInfo(eq(member), any())).thenReturn(mockInfo);
        when(mockInfo.getGeneratorType()).thenReturn(ObjectIdGenerators.PropertyGenerator.class);
        when(mockInfo.getPropertyName()).thenReturn("id");
        when(mockInfo.getScope()).thenReturn("scope");

        SettableBeanProperty idProp = mock(SettableBeanProperty.class);
        when(idProp.getType()).thenReturn(ctxt.getTypeFactory().constructType(String.class));

        // Mock findProperty behavior via a spy or controlled subclass if possible, 
        // but here we rely on the fact that we can't easily override findProperty in the real class without a full setup.
        // Since findProperty is protected, we'll assume the test environment allows us to mock the deserializer.
        TestBeanDeserializer spyDeser = spy(deser);
        doReturn(idProp).when(spyDeser).findProperty("id");

        JavaType idType = ctxt.getTypeFactory().constructType(String.class);
        when(ctxt.constructType(idType)).thenReturn(idType);
        when(ctxt.getTypeFactory().findTypeParameters(any(), any())).thenReturn(Collections.singletonList(mock(JavaType.class)));
        when(ctxt.findRootValueDeserializer(any())).thenReturn(mock(JsonDeserializer.class));
        when(ctxt.objectIdResolverInstance(any(), any())).thenReturn(mock(ObjectIdResolver.class));

        JsonDeserializer<?> result = spyDeser.createContextual(ctxt, property);
        assertNotNull(result);
        verify(spyDeser).withObjectIdReader(any(ObjectIdReader.class));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCreateContextual_WithObjectIdInfo_PropertyGenerator_Fail() throws Exception {
        TestBeanDeserializer deser = createDeserializer();
        AnnotatedMember member = mock(AnnotatedMember.class);
        when(property.getMember()).thenReturn(member);

        ObjectIdInfo mockInfo = mock(ObjectIdInfo.class);
        when(intr.findObjectIdInfo(member)).thenReturn(mockInfo);
        when(intr.findObjectReferenceInfo(eq(member), any())).thenReturn(mockInfo);
        when(mockInfo.getGeneratorType()).thenReturn(ObjectIdGenerators.PropertyGenerator.class);
        when(mockInfo.getPropertyName()).thenReturn("missing");

        TestBeanDeserializer spyDeser = spy(deser);
        doReturn(null).when(spyDeser).findProperty("missing");
        when(spyDeser.handledType()).thenReturn(Object.class);

        spyDeser.createContextual(ctxt, property);
    }

    @Test
    public void testCreateContextual_WithObjectIdInfo_OtherGenerator() throws Exception {
        TestBeanDeserializer deser = createDeserializer();
        AnnotatedMember member = mock(AnnotatedMember.class);
        when(property.getMember()).thenReturn(member);

        ObjectIdInfo mockInfo = mock(ObjectIdInfo.class);
        when(intr.findObjectIdInfo(member)).thenReturn(mockInfo);
        when(intr.findObjectReferenceInfo(eq(member), any())).thenReturn(mockInfo);
        when(mockInfo.getGeneratorType()).thenReturn(ObjectIdGenerators.UUIDGenerator.class);
        when(mockInfo.getPropertyName()).thenReturn("id");

        JavaType genType = ctxt.getTypeFactory().constructType(ObjectIdGenerator.class);
        JavaType idType = ctxt.getTypeFactory().constructType(String.class);
        when(ctxt.constructType(any())).thenReturn(idType);
        when(ctxt.getTypeFactory().findTypeParameters(any(), any())).thenReturn(Collections.singletonList(mock(JavaType.class)));
        when(ctxt.objectIdGeneratorInstance(any(), any())).thenReturn(mock(ObjectIdGenerator.class));
        when(ctxt.findRootValueDeserializer(any())).thenReturn(mock(JsonDeserializer.class));
        when(ctxt.objectIdResolverInstance(any(), any())).thenReturn(mock(ObjectIdResolver.class));

        TestBeanDeserializer spyDeser = spy(deser);
        JsonDeserializer<?> result = spyDeser.createContextual(ctxt, property);
        assertNotNull(result);
    }

    @Test
    public void testCreateContextual_WithIgnorableProperties() throws Exception {
        TestBeanDeserializer deser = createDeserializer();
        AnnotatedMember member = mock(AnnotatedMember.class);
        when(property.getMember()).thenReturn(member);
        when(intr.findObjectIdInfo(member)).thenReturn(null);

        JsonIgnoreProperties.Value ignorals = mock(JsonIgnoreProperties.Value.class);
        when(intr.findPropertyIgnorals(member)).thenReturn(ignorals);
        when(ignorals.findIgnoredForDeserialization()).thenReturn(new HashSet<>(Arrays.asList("prop1")));

        TestBeanDeserializer spyDeser = spy(deser);
        spyDeser.createContextual(ctxt, property);
        verify(spyDeser).withIgnorableProperties(anySet());
    }

    @Test
    public void testCreateContextual_WithJsonFormatShapeArray() throws Exception {
        TestBeanDeserializer deser = createDeserializer();
        AnnotatedMember member = mock(AnnotatedMember.class);
        when(property.getMember()).thenReturn(member);
        when(intr.findObjectIdInfo(member)).thenReturn(null);

        JsonFormat.Value format = JsonFormat.Value.forShape(JsonFormat.Shape.ARRAY);
        // Using a spy to mock findFormatOverrides which is protected
        TestBeanDeserializer spyDeser = spy(deser);
        doReturn(format).when(spyDeser).findFormatOverrides(any(), any(), any());

        JsonDeserializer<?> result = spyDeser.createContextual(ctxt, property);
        // In our TestBeanDeserializer, asArrayDeserializer returns 'this'
        assertEquals(spyDeser, result);
    }

    @Test
    public void testCreateContextual_WithCaseInsensitivity() throws Exception {
        TestBeanDeserializer deser = createDeserializer();
        AnnotatedMember member = mock(AnnotatedMember.class);
        when(property.getMember()).thenReturn(member);
        when(intr.findObjectIdInfo(member)).thenReturn(null);

        JsonFormat.Value format = JsonFormat.Value.forFeature(JsonFormat.Feature.ACCEPT_CASE_INSENSITIVE_PROPERTIES);

        TestBeanDeserializer spyDeser = spy(deser);
        doReturn(format).when(spyDeser).findFormatOverrides(any(), any(), any());

        // Mock BeanPropertyMap behavior
        BeanPropertyMap mockProps = mock(BeanPropertyMap.class);
        BeanPropertyMap newProps = mock(BeanPropertyMap.class);
        when(spyDeser._beanProperties).thenReturn(mockProps);
        when(mockProps.withCaseInsensitivity(true)).thenReturn(newProps);

        spyDeser.createContextual(ctxt, property);
        verify(spyDeser).withBeanProperties(newProps);
    }
}
